CREATE OR REPLACE FUNCTION public._notify(_uid uuid,_type text,_key text,_url text DEFAULT '/today') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM profiles WHERE id=_uid AND account_status='active') AND coalesce((SELECT (enabled->>_type)::boolean FROM notification_preferences WHERE user_id=_uid),_type<>'prayer') THEN INSERT INTO notifications(user_id,type,event_key,url) VALUES(_uid,_type,_key,_url) ON CONFLICT(user_id,type,event_key) DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public._notify(uuid,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public._notify(uuid,text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.register_push(_endpoint text,_p256dh text,_auth text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND account_status='active' AND NOT is_demo) THEN RAISE EXCEPTION 'unauthorized'; END IF; IF length(_endpoint)>2048 OR _endpoint !~ '^https://([a-z0-9-]+\.)*(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|web\.push\.apple\.com|wns\.windows\.com|notify\.windows\.com)/' OR _p256dh !~ '^[A-Za-z0-9_-]{80,100}$' OR _auth !~ '^[A-Za-z0-9_-]{20,30}$' THEN RAISE EXCEPTION 'invalid_subscription'; END IF; INSERT INTO push_subscriptions(user_id,endpoint,p256dh,auth) VALUES(auth.uid(),_endpoint,_p256dh,_auth) ON CONFLICT(endpoint) DO UPDATE SET p256dh=excluded.p256dh,auth=excluded.auth WHERE push_subscriptions.user_id=auth.uid(); INSERT INTO notification_preferences(user_id,push_enabled) VALUES(auth.uid(),true) ON CONFLICT(user_id) DO UPDATE SET push_enabled=true; END $$;
REVOKE ALL ON FUNCTION public.register_push(text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.register_push(text,text,text) TO authenticated;
ALTER TABLE public.notifications ADD COLUMN next_attempt_at timestamptz NOT NULL DEFAULT now();
CREATE OR REPLACE FUNCTION public.claim_notification_pushes() RETURNS SETOF public.notifications LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ WITH batch AS (SELECT n.id FROM notifications n JOIN notification_preferences p ON p.user_id=n.user_id JOIN profiles pr ON pr.id=n.user_id WHERE n.push_sent_at IS NULL AND n.attempts<5 AND n.next_attempt_at<=now() AND n.created_at>now()-interval '1 day' AND p.push_enabled AND coalesce((p.enabled->>n.type)::boolean,n.type<>'prayer') AND NOT pr.is_demo AND pr.account_status='active' AND EXISTS(SELECT 1 FROM push_subscriptions s WHERE s.user_id=n.user_id) ORDER BY n.created_at LIMIT 100 FOR UPDATE OF n SKIP LOCKED) UPDATE notifications n SET attempts=n.attempts+1,next_attempt_at=now()+interval '10 minutes' FROM batch WHERE n.id=batch.id RETURNING n.*; $$;
REVOKE ALL ON FUNCTION public.claim_notification_pushes() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_notification_pushes() TO service_role;
CREATE OR REPLACE FUNCTION public.enqueue_timed_notifications() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record; d date; local_now timestamp; sid uuid; score record; b record; a record; pc record; prayer record; n integer:=0; BEGIN FOR p IN SELECT pr.*,up.prayer_reminder,up.boss_alerts FROM profiles pr LEFT JOIN user_preferences up ON up.user_id=pr.id WHERE pr.onboarded AND pr.account_status='active' AND NOT pr.is_demo LOOP local_now:=now() AT TIME ZONE p.timezone; d:=local_now::date; SELECT e.season_id INTO sid FROM season_entries e JOIN seasons s ON s.id=e.season_id WHERE e.user_id=p.id AND NOT s.is_demo AND d BETWEEN s.starts_on AND s.ends_on ORDER BY e.joined_at DESC LIMIT 1; IF sid IS NULL THEN CONTINUE; END IF; IF local_now::time BETWEEN '08:00'::time AND '08:10'::time THEN PERFORM _notify(p.id,'morning',d::text); END IF; SELECT * INTO score FROM daily_scores WHERE user_id=p.id AND season_id=sid AND day=d; IF local_now::time BETWEEN '21:00'::time AND '21:10'::time AND coalesce(score.completion,0)<0.6 THEN PERFORM _notify(p.id,'risk',d::text); END IF; IF p.prayer_reminder THEN FOR pc IN SELECT * FROM prayer_cache WHERE user_id=p.id AND day=d LOOP FOR prayer IN SELECT * FROM jsonb_each_text(pc.times) LOOP IF local_now::time >= (prayer.value::time - interval '10 minutes')::time AND local_now::time < prayer.value::time THEN PERFORM _notify(p.id,'prayer',d::text||':'||prayer.key); END IF; END LOOP; END LOOP; END IF; IF coalesce(p.boss_alerts,true) THEN FOR b IN SELECT id FROM bosses WHERE season_id=sid AND NOT archived AND ends_at>now() AND ends_at<=now()+interval '24 hours' LOOP PERFORM _notify(p.id,'boss',b.id::text,'/boss'); END LOOP; END IF; FOR a IN SELECT * FROM announcements WHERE scheduled_at<=now() AND scheduled_at>now()-interval '1 day' AND is_demo=false AND (country IS NULL OR country=p.country_code) AND (language IS NULL OR language=p.language) AND (season_id IS NULL OR season_id=sid) LOOP PERFORM _notify(p.id,'broadcast',a.id::text); END LOOP; n:=n+1; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.enqueue_timed_notifications() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.enqueue_timed_notifications() TO service_role;